// Пара free ↔ user2 на карте (#0f19c0, #f3fc59): оба 56 лет и по умолчанию ищут 21–35, поэтому друг друга не видят.
// На время теста возраст расширяется до 18–99 у обоих (как в date-now 2.1), в finally — возврат, шаринг выкл., сессии сохраняются.
import { expect, type Page } from '@playwright/test';
import { setupMapUser, enableSharing, disableSharing, openMap, fetchNearby, type NearbyRow } from './map-helpers';
import { widenAgePrefs, restoreAgePrefs, type AgePrefs } from '../date-now/date-now-helpers';
import { saveSession } from '../_shared/session';

export const USER2_NAME = 'QA דתי';

export type Pair = { free: Page; user2: Page; prefs: (AgePrefs | undefined)[] };

// Открыть обе роли, расширить возраст, шаринг: free вкл., user2 — по флагу.
export async function setupPair(asUser: (id: string) => Promise<Page>, user2Sharing: boolean): Promise<Pair> {
  const free = await asUser('free');
  const user2 = await asUser('user2');
  await setupMapUser(free, 'free');
  await setupMapUser(user2, 'user2');
  const pair: Pair = { free, user2, prefs: [] };
  try {
    pair.prefs.push(await widenAgePrefs(free));
    pair.prefs.push(await widenAgePrefs(user2));
    if (user2Sharing) await enableSharing(user2);
    else await disableSharing(user2);
    await enableSharing(free);
    // Сосед появляется на открытой карте (обновление без перезагрузки — #0f19c0).
    if (user2Sharing) await expect(pinOf(free, USER2_NAME)).toBeVisible({ timeout: 60_000 });
  } catch (e) {
    // Подготовка упала — всё равно вернуть возраст и выключить шаринг (тест получит undefined и не сможет сам).
    await teardownPair(pair).catch(() => {});
    throw e;
  }
  return pair;
}

export async function teardownPair(p: Pair | undefined) {
  if (!p) return;
  await disableSharing(p.free).catch(() => {});
  await disableSharing(p.user2).catch(() => {});
  try {
    for (const pr of p.prefs) await restoreAgePrefs(pr);
  } finally {
    await saveSession(p.free, 'free');
    await saveSession(p.user2, 'user2');
  }
}

// Пин другого пользователя на карте (маркер Leaflet с title = имя).
export const pinOf = (page: Page, name: string) => page.getByRole('button', { name, exact: true });

// Расстояние в метрах между двумя точками (гаверсинус).
export function metersBetween(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const R = 6371000;
  const rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

// Количество знаков после точки в числе из JSON.
export const decimals = (n: unknown) => (String(n).split('.')[1] ?? '').length;

// nearby_live с перезагрузкой карты; ответ старой страницы (фоновый опрос в момент перезагрузки) теряет тело —
// тогда повторяем (до 3 раз). Без пауз.
export async function fetchNearbyStable(page: Page): Promise<NearbyRow[]> {
  let lastErr: unknown;
  for (let i = 0; i < 3; i++) {
    try {
      return await fetchNearby(page);
    } catch (e) {
      lastErr = e;
      if (!String(e).includes('getResponseBody') && !String(e).includes('No resource')) throw e;
    }
  }
  throw lastErr;
}

export { openMap };
